CREATE OR REPLACE FUNCTION profile_data_private.schema_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;actual jsonb;expected jsonb;fk jsonb;names text[]:=array['public.user_profiles'];begin
 -- Exact approved full application delta; unknown unlinked application tables
 -- also fail closed. Managed namespace checks remain the original fixed helper.
 if not result_data_private.infrastructure_supported_v1() or profile_data_private.digest_v1((select coalesce(jsonb_agg(jsonb_build_object('relation',n.nspname||'.'||c.relname,'columns',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(pg_get_constraintdef(k.oid) order by k.conname) from pg_constraint k where k.conrelid=c.oid)) order by n.nspname,c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and n.nspname not in('pg_catalog','information_schema','extensions','auth','result_data_private','storage','realtime','_realtime','vault','supabase_functions','supabase_migrations'))::text)<> '75695f209c10f7d1486505632ada19c18337bfa099680caad726a3984d666ec9' then return false;end if;
